from content_helpers import code, output, choice, lesson, section, program
from content_06 import with_functions, example

def sections():
    point = 'struct Point { int x = 0; int y = 0; };'
    return [section("objects", "12. Структуры и классы", "Объедините данные и операции, сохраняя понятные правила состояния.", [
        lesson("struct", "Запись struct", "Дайте связанным полям общее имя.",
            "struct Point { int x=0; int y=0; }; определяет новый тип с двумя полями. После закрывающей скобки определения нужна точка с запятой. Point p; создаёт объект, p.x обращается к полю. Point p{3,4}; инициализирует поля агрегата по порядку объявления. У каждого объекта собственные поля; Point q=p копирует значения.\n\nСтруктура полезна вместо параллельных массивов: имя товара, количество и цена принадлежат одной записи. std::vector<Point> хранит несколько точек, как vector<int> хранил числа. Передача const Point& позволяет читать поля без копирования и без изменения через ссылку.\n\nУказатель на структуру даёт доступ к полям через стрелку: Point* ptr = &p; тогда ptr->x — то же, что (*ptr).x. Стрелка читается короче и подчёркивает, что доступ идёт через указатель; она понадобится для узлов связных списков в поздних уроках.",
            example(point, 'Point p{3, 4};\nPoint q = p;\nq.x = 9;\nstd::cout << p.x << " " << q.x;'),
            "struct в C++ — полноценный пользовательский тип, не «просто контейнер без функций». У struct и class главным базовым различием служат уровни доступа по умолчанию; методы и конструкторы могут быть у обоих.",
            "Поля связывают данные одной сущности. Копия записи имеет собственные значения полей.", [
                with_functions(code("point", "Координаты станции", 'Определите Point с полями x,y. Ввод: x,y (−100…100). Считайте в поля и выведите y x через пробел.', 'Point p;\nstd::cin >> p.x >> p.y;\nstd::cout << p.y << " " << p.x;', [("3 -4", "-4 3"), ("0 0", "0 0"), ("-100 100", "100 -100"), ("5 5", "5 5"), ("0 -1", "-1 0")], ["Создайте объект до обращения к полям.", "Используйте p.x и p.y в cin и cout."], "Доступ через точку связывает поле с конкретным объектом."), point),
                with_functions(code("copy", "Копия координат", 'Ввод: x,y (−100…100). Создайте Point p, скопируйте в q, увеличьте только q.x на 1. Выведите p.x и q.x.', 'Point p;\nstd::cin >> p.x >> p.y;\nPoint q = p;\n++q.x;\nstd::cout << p.x << " " << q.x;', [("3 4", "3 4"), ("-1 0", "-1 0"), ("100 -100", "100 101"), ("-100 100", "-100 -99"), ("0 0", "0 1")], ["Point q=p создаёт отдельный объект.", "Изменяйте q.x, не p.x."], "Обычные поля int копируются по значению."), point),
                choice("structclass", "Возможности struct", 'Может ли struct в C++ иметь методы и конструкторы?', ["Да", "Нет, это разрешено только class", "Только если все поля double"], 0, ["Это пользовательский классовый тип.", "Различие по умолчанию связано с доступом, не запретом методов."], "Не переносите ограничения других языков на struct C++."),
                with_functions(code("distance", "Манхэттенский путь", 'Ввод: x,y (−100…100) точки. Напишите int route(const Point& p), возвращающую |x|+|y| без std::abs, через ветвления. Выведите route.', 'Point p;\nstd::cin >> p.x >> p.y;\nstd::cout << route(p);', [("-3 4", "7"), ("0 0", "0"), ("-100 100", "200"), ("100 -100", "200"), ("0 -100", "100"), ("-5 -5", "10")], ["Поля читаются через p.x и p.y.", "Для каждого отрицательного значения возьмите унарный минус."], "Контракт малых координат исключает переполнение при смене знака.", difficulty=2), point + '\nint route(const Point& p) {\n    int x = p.x, y = p.y;\n    if (x < 0) { x = -x; }\n    if (y < 0) { y = -y; }\n    return x + y;\n}'),
                with_functions(code("arrow", "Точка через стрелку", 'Ввод: x,y (−100…100). Создайте Point p, затем Point* ptr = &p. Через ptr увеличьте поле x на 1 и выведите новые x и y через пробел, обращаясь к полям через ptr.', 'int x = 0, y = 0;\nstd::cin >> x >> y;\nPoint p;\np.x = x;\np.y = y;\nPoint* ptr = &p;\nptr->x += 1;\nstd::cout << ptr->x << " " << ptr->y;', [("0 0", "1 0"), ("5 3", "6 3"), ("-1 2", "0 2"), ("100 100", "101 100"), ("-100 -100", "-99 -100")], ["Стрелка ptr->x означает (*ptr).x.", "Сначала заполните поля, затем работайте через указатель."], "Стрелка — то же разыменование с доступом к полю, но записанное короче."), point)
            ], ["struct", "поля", "копирование", "указатели"]),
        lesson("methods", "Методы и const", "Разместите операцию рядом с данными.",
            "Метод — функция, вызываемая у объекта: counter.add();. Внутри метода поля этого объекта доступны по имени. Метод int value() const обещает не менять обычное состояние объекта через this и может вызываться у const-объекта. Для наших простых классов это проверяемое ограничение чтения.\n\nВ class поля и методы по умолчанию private. Раздел public: открывает интерфейс. Частные поля не читаются напрямую из main; доступ идёт через методы. Это не секретность от злоумышленника, а языковая граница для сохранения правил состояния. Начальные значения полей защищают от случайного неинициализированного состояния.",
            example('class Counter {\n    int count_ = 0;\npublic:\n    void add() { ++count_; }\n    int value() const { return count_; }\n};', 'Counter c;\nc.add();\nstd::cout << c.value();'),
            "const-метод — не обещание отсутствия всех возможных побочных эффектов во всей программе: существуют mutable, внешние ресурсы и другие пути доступа. В рамках этого класса value только читает count_. Делайте конкретные утверждения, не преувеличивая смысл ключевого слова.",
            "Методы меняют или читают состояние конкретного объекта. const у читающего метода делает намерение явным.", [
                with_functions(code("counter", "Счётчик посадок", 'Создайте Counter с private int count_=0, public add() и value() const. Метод add увеличивает count_ на 1, а value возвращает его значение. Ввод: n (0…100). Вызовите add n раз и выведите value.', 'int n = 0;\nstd::cin >> n;\nCounter c;\nfor (int i = 0; i < n; ++i) { c.add(); }\nstd::cout << c.value();', [("3", "3"), ("0", "0"), ("1", "1"), ("100", "100"), ("50", "50")], ["main не должен обращаться к count_ напрямую.", "Открытые методы управляют состоянием и возвращают наблюдаемое значение."], "Класс отделяет представление счётчика от действий над ним."), 'class Counter {\n    int count_ = 0;\npublic:\n    void add() { ++count_; }\n    int value() const { return count_; }\n};'),
                with_functions(code("points", "Сумма полей методом", 'Создайте struct Pair с x,y и методом int sum() const. Ввод: x,y (−100…100). Выведите вызов sum.', 'Pair p;\nstd::cin >> p.x >> p.y;\nstd::cout << p.sum();', [("3 4", "7"), ("-2 2", "0"), ("-100 100", "0"), ("100 100", "200"), ("-100 -100", "-200")], ["У struct поля открыты по умолчанию.", "Внутри метода return x+y обращается к полям текущего объекта."], "Методы допустимы и у struct."), 'struct Pair {\n    int x = 0, y = 0;\n    int sum() const { return x + y; }\n};'),
                choice("constmethod", "Чтение const-объекта", 'Зачем помечать простой читающий метод value() как const?', ["Чтобы разрешить его вызов у const-объекта и запретить обычное изменение его полей через этот метод", "Чтобы результат всегда вычислялся при компиляции", "Чтобы метод мог вызываться только один раз"], 0, ["const и constexpr — не одно и то же.", "Это ограничение доступа к состоянию объекта."], "Контракт чтения виден и вызывающему коду, и компилятору."),
                with_functions(code("two", "Независимые счётчики", 'Используйте Counter с начальным значением 0: add увеличивает счётчик на 1, value возвращает его значение. Ввод: a,b (0…100). Создайте два Counter, увеличьте первый a раз, второй b раз, выведите значения через пробел.', 'int a = 0, b = 0;\nstd::cin >> a >> b;\nCounter first, second;\nfor (int i = 0; i < a; ++i) { first.add(); }\nfor (int i = 0; i < b; ++i) { second.add(); }\nstd::cout << first.value() << " " << second.value();', [("2 5", "2 5"), ("0 0", "0 0"), ("0 100", "0 100"), ("100 0", "100 0"), ("50 50", "50 50")], ["Поля принадлежат объектам, а не единому глобальному счётчику.", "Вызывайте метод у нужного имени объекта."], "Один тип задаёт правила для множества независимых состояний."), 'class Counter {\n    int count_ = 0;\npublic:\n    void add() { ++count_; }\n    int value() const { return count_; }\n};')
            ], ["методы", "class", "const"]),
        lesson("constructors", "Конструкторы и инварианты", "Создавайте объект сразу в допустимом состоянии.",
            "Конструктор имеет имя типа и не имеет типа результата: Meter(int start) : value_(start) {}. Список после двоеточия инициализирует поля до выполнения тела конструктора. Это не обычный вызов метода после создания. Поля инициализируются в порядке объявления в классе, не в порядке списка.\n\nИнвариант — правило допустимого состояния. Например, заряд батареи всегда 0…100. Конструктор может ограничить начальный заряд, а метод charge добавляет энергию с ограничением 100. Закрытые поля не позволяют main обойти эти методы случайным присваиванием. explicit перед одноаргументным конструктором запрещает нежелательное неявное преобразование; прямое Battery b(start) остаётся допустимым.",
            example('class Meter {\n    int value_;\npublic:\n    explicit Meter(int start) : value_(start) {}\n    int value() const { return value_; }\n};', 'Meter m(7);\nstd::cout << m.value();'),
            "Присваивание полю в теле и инициализация поля — разные стадии. Для int разница может казаться незаметной, но const-поля и ссылочные поля вообще требуют правильной инициализации. Не учите привычку «сначала создать как попало, потом исправить».",
            "Конструктор задаёт начальное состояние, методы сохраняют инвариант, private отделяет внутренности от интерфейса.", [
                with_functions(code("meter", "Начальное показание", 'Создайте Meter с private int value_, explicit Meter(int start), value() const. Ввод: start (−100…100). Создайте объект и выведите значение.', 'int start = 0;\nstd::cin >> start;\nMeter m(start);\nstd::cout << m.value();', [("7", "7"), ("-5", "-5"), ("-100", "-100"), ("100", "100"), ("0", "0")], ["У конструктора нет return type.", "Инициализируйте value_ через : value_(start)."], "Прямое создание с аргументом явно выражает начальное состояние."), 'class Meter {\n    int value_;\npublic:\n    explicit Meter(int start) : value_(start) {}\n    int value() const { return value_; }\n};'),
                with_functions(code("battery", "Заряд не выше 100", 'Создайте Battery с начальным зарядом start (0…100), методом charge(int bonus) для bonus (0…100) с ограничением 100 и value() const. main читает start,bonus и выводит заряд после charge.', 'int start = 0, bonus = 0;\nstd::cin >> start >> bonus;\nBattery b(start);\nb.charge(bonus);\nstd::cout << b.value();', [("90 30", "100"), ("20 15", "35"), ("0 0", "0"), ("100 0", "100"), ("100 100", "100"), ("99 1", "100"), ("0 100", "100"), ("50 50", "100")], ["Сначала сложите заряд и bonus, затем ограничьте верхнюю границу.", "Метод должен менять закрытое поле, не печатать ответ."], "Контракт неотрицательного bonus сохраняет нижнюю границу 0.", difficulty=2), 'class Battery {\n    int energy_;\npublic:\n    explicit Battery(int start) : energy_(start) {}\n    void charge(int bonus) {\n        energy_ += bonus;\n        if (energy_ > 100) { energy_ = 100; }\n    }\n    int value() const { return energy_; }\n};'),
                choice("order", "Порядок полей", 'В каком порядке инициализируются поля класса?', ["В порядке объявления полей в классе", "Всегда по алфавиту", "В произвольном порядке списка инициализации"], 0, ["Список конструктора не переставляет сами поля.", "Объявления определяют устойчивый порядок."], "Не делайте инициализацию одного поля зависимой от ещё не инициализированного последующего."),
                with_functions(code("rectangle", "Площадь объекта", 'Создайте Rectangle(int w,int h) с закрытыми полями и area() const. Ввод: w,h (0…100). Выведите площадь.', 'int w = 0, h = 0;\nstd::cin >> w >> h;\nRectangle r(w, h);\nstd::cout << r.area();', [("3 4", "12"), ("0 9", "0"), ("100 100", "10000"), ("1 0", "0"), ("0 0", "0"), ("10 10", "100")], ["Имена параметров могут отличаться от полей.", "Список : width_(w), height_(h) создаёт начальные значения."], "Операция area зависит только от корректно созданного состояния."), 'class Rectangle {\n    int width_;\n    int height_;\npublic:\n    Rectangle(int w, int h) : width_(w), height_(h) {}\n    int area() const { return width_ * height_; }\n};')
            ], ["конструкторы", "инварианты", "инициализация"]),
        lesson("encapsulation", "Мини-проект: склад записей", "Объедините коллекцию объектов и проверяемые операции.",
            "Запись Item может содержать std::string name и int count. vector<Item> хранит весь склад, а функции читают коллекцию через const-ссылку или изменяют конкретный Item&. Если для записи есть строгие ограничения, class с методами может защитить их лучше открытого struct. Если это простые данные для передачи, struct остаётся уместным.\n\nДля поиска товара сравнивайте имена точно; контракт может гарантировать уникальность. Проверка количества до списания не должна молча делать остаток отрицательным. Метод bool take(int amount) может вернуть false без изменения состояния, если товара недостаточно. В этом уроке amount гарантированно неотрицателен.",
            example('struct Item { std::string name; int count = 0; };', 'Item item{"Food", 7};\nstd::cout << item.name << " " << item.count;').replace('#include <iostream>', '#include <iostream>\n#include <string>'),
            "Инкапсуляция означает контроль допустимых операций, а не обязательную замену каждого поля отдельной парой getter/setter. Метод «списать, если возможно» выражает атомарное правило лучше, чем свободное изменение количества снаружи.",
            "Выбирайте struct для простых записей и class для состояния с правилами. Ошибка операции не должна частично менять состояние.", [
                with_functions(code("stock", "Товар с наибольшим запасом", 'Ввод: n (1…100), затем n пар name count; name — латинское слово, count (0…100). Сохраните в vector<Item>. Выведите имя первого товара с максимальным count.', 'int n = 0;\nstd::cin >> n;\nstd::vector<Item> items(n);\nfor (int i = 0; i < n; ++i) { std::cin >> items[i].name >> items[i].count; }\nint best = 0;\nfor (int i = 1; i < n; ++i) {\n    if (items[i].count > items[best].count) { best = i; }\n}\nstd::cout << items[best].name;', [("3 Food 7 Air 9 Tools 9", "Air"), ("1 Box 0", "Box"), ("1 Box 5", "Box"), ("2 A 5 B 5", "A"), ("3 A 0 B 0 C 1", "C"), ("3 A 100 B 99 C 100", "A")], ["При равенстве не заменяйте best.", "Сравнивайте count, а выводите name того же объекта."], "Одна запись сохраняет связь имени и количества.", headers="iostream string vector", difficulty=2), 'struct Item { std::string name; int count = 0; };'),
                with_functions(code("take", "Безопасное списание", 'Создайте Stock(int initial), bool take(int amount), int count() const. Ввод: initial,amount (0…100). При нехватке take возвращает false и ничего не меняет. Выведите успех (1/0) и остаток.', 'int initial = 0, amount = 0;\nstd::cin >> initial >> amount;\nStock stock(initial);\nbool success = stock.take(amount);\nstd::cout << success << " " << stock.count();', [("7 3", "1 4"), ("2 5", "0 2"), ("0 0", "1 0"), ("5 5", "1 0"), ("5 6", "0 5"), ("100 100", "1 0")], ["Проверка количества должна предшествовать вычитанию.", "В неуспешной ветви сразу return false."], "Неуспех оставляет прежнее состояние — это часть контракта метода.", difficulty=2), 'class Stock {\n    int count_;\npublic:\n    explicit Stock(int initial) : count_(initial) {}\n    bool take(int amount) {\n        if (amount > count_) { return false; }\n        count_ -= amount;\n        return true;\n    }\n    int count() const { return count_; }\n};'),
                choice("invariant", "Что защищает private?", 'Какой интерфейс лучше выражает правило «количество не бывает отрицательным»?', ["Метод take с проверкой допустимости до изменения", "Публичное поле без ограничений", "Метод, который сначала вычитает, а потом забывает проверить"], 0, ["Важна операция с целым контрактом.", "Проверка должна не допустить неверного состояния."], "Класс полезен, когда его интерфейс действительно сохраняет инвариант."),
                with_functions(code("total", "Стоимость запасов", 'Ввод: n (0…100), затем n пар count price (0…100). Используйте struct Item с count,price и total() const. Суммируйте стоимости в long long и выведите общий результат.', 'int n = 0;\nstd::cin >> n;\nlong long sum = 0;\nfor (int i = 0; i < n; ++i) {\n    Item item;\n    std::cin >> item.count >> item.price;\n    sum += item.total();\n}\nstd::cout << sum;', [("2 3 7 2 5", "31"), ("0", "0"), ("1 100 100", "10000"), ("2 1 100 100 1", "200"), ("3 2 50 2 25 2 25", "200"), ("2 0 100 100 0", "0"), ("1 1 1", "1")], ["Произведение одной записи помещается в int, сумма может быть больше.", "Сохраняйте сумму в long long до накопления."], "Метод записи выражает локальный расчёт, внешний цикл — общий учёт.", difficulty=2), 'struct Item {\n    int count = 0, price = 0;\n    int total() const { return count * price; }\n};')
            ], ["мини-проект", "инкапсуляция", "объекты"]),
        lesson("linkedlist", "Связный список", "Соединяйте узлы указателями вместо подряд идущей памяти.",
            "Односвязный список — цепочка узлов: struct Node { int value; Node* next; };. Голова — указатель на первый узел; пустой список — head == nullptr. Построение вставкой в голову: head = new Node{value, head}; — новый узел ссылается на прежнюю голову. Обход: for (Node* p = head; p != nullptr; p = p->next). Освобождение требует сохранить p->next до delete: Node* next = p->next; delete p; p = next;\n\nИнварианты: у непустого списка head не нулевой, последний узел указывает на nullptr. Потеря головы или переписывание next до сохранения делает оставшиеся узлы недоступными — это утечка памяти. Вставка в голову выполняется за один шаг; вставка в конец требует обхода до последнего узла. Двусвязный список добавляет указатель prev: движение в обе стороны, но больше обязательств по синхронизации при каждом изменении. Вставка нового узла между существующими — разбор по шагам с временными указателями, а не «магическое связывание».",
            program('struct Node { int value; Node* next; };\nNode c{3, nullptr};\nNode b{2, &c};\nNode a{1, &b};\nint sum = 0;\nfor (Node* p = &a; p != nullptr; p = p->next) { sum += p->value; }\nstd::cout << sum;', "iostream"),
            "head = new Node{value, head} меняет голову, а прежняя голова становится вторым узлом, поэтому порядок чтения оказывается обратным порядку вставок. delete не обнуляет указатели автоматически, а обращение к узлу после его delete — неопределённое поведение. Массив хранит элементы подряд и даёт быстрый доступ по индексу; список хранит разбросанные узлы и платит за это лишним указателем и слабой локальностью кэша — выбирайте структуру по способу использования, а не по привычке.",
            "Узел: значение плюс указатель next. Голова — единственная точка входа; пустой список — nullptr. Обход: p = p->next до nullptr. Освобождение: сохранить next до delete.", [
                with_functions(code("build", "Список из входа", 'Ввод: n (0…100), затем n значений (−100…100). Постройте односвязный список, добавляя каждый следующий элемент в голову, затем пройдите от головы и выведите значения через пробел. vector для хранения здесь не используйте.', 'int n = 0;\nstd::cin >> n;\nNode* head = nullptr;\nfor (int i = 0; i < n; ++i) {\n    int value = 0;\n    std::cin >> value;\n    head = new Node{value, head};\n}\nfor (Node* p = head; p != nullptr; p = p->next) {\n    if (p != head) { std::cout << " "; }\n    std::cout << p->value;\n}\nNode* p = head;\nwhile (p != nullptr) { Node* next = p->next; delete p; p = next; }', [("4 1 2 3 4", "4 3 2 1"), ("0", ""), ("1 7", "7"), ("3 5 5 5", "5 5 5"), ("2 -1 -2", "-2 -1"), ("5 10 20 30 40 50", "50 40 30 20 10")], ["Новый узел получает прежнюю голову в next.", "Вывод идёт от головы, то есть в обратном порядке вставки."], "Проверка вводом и выводом не доказывает устройство хранения, поэтому контракт явно требует список узлов и вставку в голову.", headers="iostream", difficulty=2), 'struct Node {\n    int value;\n    Node* next;\n};'),
                with_functions(code("listsum", "Сумма обходом", 'Ввод: n (0…100), затем n значений (−100…100). Постройте список вставкой в голову, затем одним обходом посчитайте и выведите сумму значений, не освобождая узлы до конца обхода.', 'int n = 0;\nstd::cin >> n;\nNode* head = nullptr;\nfor (int i = 0; i < n; ++i) {\n    int value = 0;\n    std::cin >> value;\n    head = new Node{value, head};\n}\nlong long sum = 0;\nfor (Node* p = head; p != nullptr; p = p->next) {\n    sum += p->value;\n}\nstd::cout << sum;\nNode* p = head;\nwhile (p != nullptr) { Node* next = p->next; delete p; p = next; }', [("4 1 2 3 4", "10"), ("0", "0"), ("1 -7", "-7"), ("3 5 5 5", "15"), ("3 100 -100 50", "50"), ("2 0 0", "0")], ["Сумма не зависит от порядка обхода.", "Условие продолжения — p != nullptr."], "Обход списка — линейный проход по указателям, аналог цикла по индексам массива.", headers="iostream", difficulty=2), 'struct Node {\n    int value;\n    Node* next;\n};'),
                with_functions(code("listfree", "Освобождение по ходу", 'Ввод: n (0…100), затем n значений (−100…100). Постройте список вставкой в голову, затем пройдите с освобождением: перед delete каждого узла сохраните его next. Выведите число узлов.', 'int n = 0;\nstd::cin >> n;\nNode* head = nullptr;\nfor (int i = 0; i < n; ++i) {\n    int value = 0;\n    std::cin >> value;\n    head = new Node{value, head};\n}\nint count = 0;\nNode* p = head;\nwhile (p != nullptr) {\n    Node* next = p->next;\n    delete p;\n    p = next;\n    ++count;\n}\nstd::cout << count;', [("4 1 2 3 4", "4"), ("0", "0"), ("1 7", "1"), ("3 5 5 5", "3"), ("6 1 2 3 4 5 6", "6")], ["delete без сохранённого next лишает путь к остальным узлам.", "Освобождение завершается, когда p становится nullptr."], "Освобождение списка — осторожная последовательность delete в порядке обхода, а не одно действие.", difficulty=2), 'struct Node {\n    int value;\n    Node* next;\n};'),
                choice("listorder", "Порядок вставки в голову", 'Значения 1, 2, 3 вставлялись по очереди в голову пустого списка. В каком порядке они читаются от головы?', ["3 2 1", "1 2 3", "Порядок не определён"], 0, ["Каждая вставка помещает новый узел первым.", "Прежняя голова уходит на вторую позицию."], "Вставка в голову удобна и быстра, но обращает порядок чтения относительно вставки."),
                choice("listleak", "Потерянный хвост", 'В узле списка переписали поле next, не сохранив прежнее значение, и других указателей на хвост нет. Что станет с остальными узлами?', ["Они автоматически освободятся вместе с текущим", "Они станут недоступны и не будут освобождены", "Они переместятся в начало списка"], 1, ["Единственный путь к хвосту шёл через перезаписанное поле.", "Освобождение без доступного пути — утечка памяти."], "Указатель next — единственная связь цепочки; её потеря делает узлы недостижимыми."),
                choice("dlinked", "Двусвязный список", 'Чем двусвязный список отличается от односвязного в обслуживании?', ["Ничем, только названием", "Узлы хранят также prev; вставки и удаления синхронизируют оба направления", "В нём нельзя хранить строки"], 1, ["prev даёт движение назад и удаление узла без обхода от головы.", "Каждая операция должна корректно обновлять next и prev."], "Дополнительный указатель покупает скорость перемещения ценой большего числа обязательных обновлений.")
            ], ["связные списки", "узлы", "утечки"]),
        lesson("stackqueue", "Стек и очередь", "Соблюдайте порядок извлечения: LIFO и FIFO.",
            "Стек — LIFO: последним добавленный извлекается первым. На vector это push_back и pop_back с проверкой непустоты: back() читает вершину, pop_back её удаляет. Очередь — FIFO: первым извлекается самый старый элемент. На односвязном списке удобно хранить указатели на голову и хвост: вставка в хвост и извлечение из головы выполняются за один шаг.\n\nКаждая структура обязана сохранять свой порядок: смешение операций с разных концов превращает одну структуру в другую. Перед back() и pop_back() проверяйте empty(): операции над пустым стеком недопустимы. Классическая задача на стек — проверка скобочного баланса: открывающая скобка добавляется в стек, закрывающая обязана совпасть с вершиной; пустой стек в конце означает баланс. std::stack и std::queue стандартной библиотеки — адаптеры над контейнерами; здесь ручные версии объясняют, откуда берётся порядок извлечения.",
            program('std::vector<int> stack;\nstack.push_back(1);\nstack.push_back(2);\nstd::cout << stack.back() << " ";\nstack.pop_back();\nstd::cout << stack.back();', "iostream vector"),
            "Стек на vector и очередь на списке демонстрируют, что порядок определяется выбранными концами, а не контейнером. Ручная очередь показывает, зачем нужен указатель на хвост: без него каждый приход обходил бы весь список. Скобочный баланс использует свойство стека: последняя незакрытая скобка закрывается первой.",
            "Стек: push_back/pop_back на vector с проверкой empty(). Очередь: вставка в хвост, извлечение из головы; на списке хранят head и tail.", [
                code("brackets", "Скобочный баланс", 'Ввод: одна строка из символов ()[]{} длиной 0…1000. Выведите Yes, если скобки сбалансированы: каждая закрывающая совпадает с последней незакрытой открывающей, и в конце нет незакрытых. Иначе No. Пустая строка сбалансирована. Используйте стек.', 'std::string line;\nstd::getline(std::cin, line);\nstd::vector<char> stack;\nbool balanced = true;\nfor (char c : line) {\n    if (c == \'(\' || c == \'[\' || c == \'{\') {\n        stack.push_back(c);\n    } else {\n        char expected = \'(\';\n        if (c == \']\') { expected = \'[\'; }\n        if (c == \'}\') { expected = \'{\'; }\n        if (stack.empty() || stack.back() != expected) { balanced = false; break; }\n        stack.pop_back();\n    }\n}\nif (balanced && stack.empty()) { std::cout << "Yes"; }\nelse { std::cout << "No"; }', [("(())", "Yes"), ("([)]", "No"), ("", "Yes"), ("(", "No"), ("()[]{}", "Yes"), ("{[()]}", "Yes"), (")", "No"), ("(()", "No")], ["Закрывающая скобка сверяется с вершиной стека.", "После строки стек обязан быть пустым."], "Стек хранит незакрытые скобки; несовпадение вершины или пустой стек при закрывающей означают дисбаланс.", headers="iostream string vector", difficulty=2),
                with_functions(code("fifo", "Очередь на списке", 'Ввод: n (0…100), затем n значений (−100…100). Постройте очередь на односвязном списке с указателями на голову и хвост: каждый новый узел вставляйте в хвост. Извлеките все узлы из головы, выводя значения через пробел, и освободите каждый после чтения.', 'int n = 0;\nstd::cin >> n;\nNode* head = nullptr;\nNode* tail = nullptr;\nfor (int i = 0; i < n; ++i) {\n    int value = 0;\n    std::cin >> value;\n    Node* node = new Node{value, nullptr};\n    if (tail == nullptr) { head = node; }\n    else { tail->next = node; }\n    tail = node;\n}\nwhile (head != nullptr) {\n    Node* next = head->next;\n    std::cout << head->value;\n    if (next != nullptr) { std::cout << " "; }\n    delete head;\n    head = next;\n}', [("4 1 2 3 4", "1 2 3 4"), ("0", ""), ("1 9", "9"), ("3 5 5 5", "5 5 5"), ("3 3 2 1", "3 2 1"), ("2 -7 8", "-7 8")], ["Первый узел становится и головой, и хвостом.", "Извлечение всегда из головы сохраняет порядок прихода."], "Указатель на хвост делает вставку одношаговой: очередь не обязана обходить список при каждом приходе.", headers="iostream", difficulty=2), 'struct Node {\n    int value;\n    Node* next;\n};'),
                choice("lifomean", "Смысл LIFO", 'Что означает LIFO?', ["Последним пришёл — первым вышел", "Первым пришёл — первым вышел", "Порядок извлечения не определён"], 0, ["Стек извлекает самый свежий элемент.", "FIFO, напротив, извлекает самый старый."], "Названия порядка — часть контракта структуры, а не детали реализации."),
                choice("stackempty", "Пустой стек", 'Что проверить перед back() и pop_back() у векторного стека?', ["empty(): операции над пустым стеком недопустимы", "size() > 1000", "Ничего: back() безопасен для пустого вектора"], 0, ["Пустой вектор не имеет вершины.", "Проверка — часть контракта операций стека."], "Ошибка пустого стека — типичный граничный случай алгоритмов на стеке."),
                choice("queueends", "Концы очереди", 'В очереди на односвязном списке с указателями head и tail какая пара операций даёт FIFO за один шаг?', ["Вставка в хвост, извлечение из головы", "Вставка в голову, извлечение из хвоста", "Обе операции в голове"], 0, ["FIFO сохраняет порядок прихода.", "Вставка в голову и извлечение из хвоста тоже дают FIFO, но извлечение потребует обхода до предпоследнего узла."], "Порядок задают выбранные концы, а стоимость шага — структура: на односвязном списке с tail только вставка в хвост и извлечение из головы выполняются за O(1).")
            ], ["стек", "очередь", "LIFO и FIFO"])
    ])]
